const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var geometry = ee.Geometry.Point([-74.0060, 40.7128]).buffer(10000); // 10 km buffer around NYC
  var start2016 = '2016-07-20';
  var end2016 = '2016-07-27';
  var years = ee.List.sequence(2001, 2010);

  // Function to mask LST image using QC band
  function maskLST(image) {
    var lst = image.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Convert to Celsius
    var qc = image.select('QC_Day');
    var qualityMask = qc.bitwiseAnd(3).lt(2); // Keep bits 0-1 = 00 or 01
    return lst.updateMask(qualityMask);
  }

  // 2. Data Acquisition for 2016
  var col2016 = ee.ImageCollection('MODIS/061/MOD11A2')
    .filterBounds(geometry)
    .filterDate(start2016, end2016);

  var count2016 = col2016.size().getInfo();
  if (count2016 === 0) {
    print("2016 Images: 0");
    print("<answer>C1</answer>");
    return;
  }

  var img2016 = maskLST(col2016.first());

  // Check valid pixels for 2016
  var stats2016 = img2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });
  var countValid2016 = stats2016.get('LST_Day_1km').getInfo();
  if (countValid2016 === 0) {
    print("2016 Valid Pixels: 0");
    print("<answer>C2</answer>");
    return;
  }

  var mean2016 = img2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  // 3. Data Acquisition for 2001-2010
  var yearMeans = [];
  var hasMissing = false;
  var hasZeroPixels = false;

  for (var i = 2001; i <= 2010; i++) {
    var start = i + '-07-20';
    var end = i + '-07-27';
    var col = ee.ImageCollection('MODIS/061/MOD11A2')
      .filterBounds(geometry)
      .filterDate(start, end);

    var count = col.size().getInfo();
    if (count === 0) {
      print(i + " Images: 0");
      hasMissing = true;
      break;
    }

    var img = maskLST(col.first());

    // Check valid pixels
    var stats = img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });
    var countValid = stats.get('LST_Day_1km').getInfo();
    if (countValid === 0) {
      print(i + " Valid Pixels: 0");
      hasZeroPixels = true;
      break;
    }

    var mean = img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    yearMeans.push(mean);
    print(i + " Mean: " + mean.toFixed(2) + " C, Pixels: " + countValid);
  }

  if (hasMissing) {
    print("<answer>C1</answer>");
    return;
  }

  if (hasZeroPixels) {
    print("<answer>C2</answer>");
    return;
  }

  // 4. Calculate 2001-2010 average
  var sum = 0;
  for (var j = 0; j < yearMeans.length; j++) {
    sum += yearMeans[j];
  }
  var avg2001_2010 = sum / yearMeans.length;

  // 5. Validation & Final Answer
  print("2016 Mean: " + mean2016.toFixed(2) + " C, Pixels: " + countValid2016);
  print("2001-2010 Avg: " + avg2001_2010.toFixed(2) + " C");

  if (mean2016 === null || avg2001_2010 === null || 
      isNaN(mean2016) || isNaN(avg2001_2010) ||
      mean2016 > 100 || mean2016 < -100 || 
      avg2001_2010 > 100 || avg2001_2010 < -100) {
    print("<answer>C3</answer>");
  } else if (mean2016 > avg2001_2010) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
